Tool response:
Tool: update_service_ticket_status
Description: Update the status of a service ticket
Parameters:
    {
      "type": "object",
      "properties": {
        "ticket_id": {
          "type": "integer",
          "description": "Internal ID of the service ticket",
          "title": "Ticket Id"
        },
        "status": {
          "type": "string",
          "const": "Resolved",
          "title": "Status",
          "description": "New status for the service ticket (must be 'Resolved')"
        }
      },
      "required": [
        "ticket_id",
        "status"
      ]
    }

Tool response:
Tool: add_service_note
Description: Add a repair note to a service ticket
Parameters:
    {
      "type": "object",
      "properties": {
        "ticket_id": {
          "type": "integer",
          "description": "Internal ID of the service ticket",
          "title": "Ticket Id"
        },
        "note": {
          "type": "string",
          "title": "Note",
          "description": "Content of the repair note"
        }
      },
      "required": [
        "ticket_id",
        "note"
      ]
    }

Tool response:
Tool: record_labor_time
Description: Record labor time for a service ticket
Parameters:
    {
      "type": "object",
      "properties": {
        "ticket_id": {
          "type": "integer",
          "description": "Internal ID of the service ticket",
          "title": "Ticket Id"
        },
        "hours": {
          "type": "number",
          "exclusiveMinimum": 0.0,
          "title": "Hours",
          "description": "Number of hours of labor time to record"
        }
      },
      "required": [
        "ticket_id",
        "hours"
      ]
    }
